from __future__ import annotations

# Decorative assets generated with Image2.5 for the portal redesign.
HERO_WEBP_B64 = ""
GLOBE_WEBP_B64 = ""

def webp_data_uri(name: str = "hero") -> str:
    key = str(name or "hero").strip().lower()
    payload = GLOBE_WEBP_B64 if key == "globe" else HERO_WEBP_B64
    return f"data:image/webp;base64,{payload}"
